PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE NOT NULL,nickname TEXT NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'USER',status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS topics(id INTEGER PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,color TEXT);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,body TEXT NOT NULL,tags TEXT NOT NULL DEFAULT '[]',topic_id INTEGER REFERENCES topics(id),status TEXT NOT NULL DEFAULT 'PUBLISHED',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),post_id INTEGER REFERENCES posts(id),url TEXT NOT NULL UNIQUE,type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ratings(post_id INTEGER REFERENCES posts(id),user_id INTEGER REFERENCES users(id),score INTEGER CHECK(score BETWEEN 1 AND 5),PRIMARY KEY(post_id,user_id));
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY,post_id INTEGER REFERENCES posts(id),user_id INTEGER REFERENCES users(id),body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),action TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,admin_id INTEGER REFERENCES users(id),target_type TEXT,target_id INTEGER,action TEXT,created_at TEXT);
CREATE INDEX IF NOT EXISTS post_created ON posts(status,created_at);
CREATE INDEX IF NOT EXISTS event_created ON events(created_at,user_id);
CREATE INDEX IF NOT EXISTS comments_post ON comments(post_id,status);
